menu = {"라떼": 4000, "모카": 4500}
orders = input().split()
counts = {}
total = 0
for o in orders:
    if o not in menu:
        continue
    counts[o] = counts.get(o, 0) + 1
    total = total + menu[o]
for k, n in counts.items():
    print(k, n)
print("합계", total)
